var seed = Math.random() * 1341;
var t;
var num, vNum;
var radius, mySize;
var sizes = [];

let colors = [];
let colors0 = "281914-1a1a1a-202020-242e30".split("-").map((a) => "#" + a);
let colors7 = "fefefe-fffffb-fafdff-fef9fb-f7fcfe".split("-").map((a) => "#" + a);
let colors8 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
let colors11 = "025159-3E848C-7AB8BF-C4EEF2-A67458".split("-").map((a) => "#" + a);
let colors12 = "10454F-506266-818274-A3AB78-BDE038".split("-").map((a) => "#" + a);
let colors13 = "D96690-F28DB2-F2C9E0-89C2D9-88E8F2".split("-").map((a) => "#" + a);
var color_setup1, color_setup2;
let color_bg;

function setup() {
	randomSeed(seed);
	// pixelDensity(1);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	color_setup1 = colors7;
	// color_setup2 = colors8;//random([colors8,colors11,colors12,colors13]);
	color_setup2 = random([colors8, colors11, colors8, colors12, colors8, colors13]);
	color_bg = "#202020";
	colors[0] = random(colors7);
	colors[1] = random(color_setup2);
	colors[2] = random(color_setup2);
	colors[3] = random(color_setup2);
	colors[4] = random(color_setup2);
	background(color_bg);
	num = 250;
	radius = mySize * 0.25;
	for (let a = 0; a < TAU; a += (Math.max(0.001, Math.abs(TAU / num)) || 1)) {
		sizes.push(random(0.1, 1))
	}

	t = 0;
}

function draw() {
	background(color_bg);
	randomSeed(seed);
	//for (let j = 0; j < 10; j++) {
	push();
	translate(width / 2, height / 2);
	rotate(random(TAU) + t);
	noFill();
	for (let i = 0; i < num; i++) {
		let a = (TAU / num) * i + t
		let x = radius * sin(a - t) / 1;
		let y = radius * cos(a - t) / random(1, 1.5);
		stroke(random(colors));
		strokeWeight(sizes[i] / 0.25);
		let d = random(radius / 10, radius / 5);
		let x_plus = 2 * random(-d, d);
		push();
		translate(x + x_plus, y + d * cos(d) / 1);
		rotate(random(TAU) + t);
		line(0, 0, cos(t / i), -d * sin(d) / 1);
		pop();

		push();
		translate(x + x_plus, y + d * cos(d) / 1);
		rotate(random(TAU) + t);
		strokeWeight(sizes[i] / 1.25);
		square(random((x + x_plus) / 3 * 4, (x + x_plus) / 3), random((y + d * cos(d) / 1) / 3 * 4, (y + d * cos(d) / 1) / 3), random(d / 5));
		pop();

		push();
		translate(x + x_plus, y + d * cos(d) / 1);
		rotate(random(TAU) + t);
		strokeWeight(sizes[i] / 1.25);
		circle(random((x + x_plus) / 2 * 3, (x + x_plus) / 2), random((y + d * cos(d) / 1) / 2 * 3, (y + d * cos(d) / 1) / 2), random(d / 10));
		pop();
	}
	pop();
	t += random(0.001, 0.005);
}


function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("0511_Energy Circle_1.3_Asteroid belt_2022", "png");
	}
}

